#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct SpriteGpuInstance2d {
    model_0: [f32; 4],
    model_1: [f32; 4],
    model_2: [f32; 4],
    model_3: [f32; 4],
    tint: [f32; 4],
    uv_transform: [f32; 4],
}

impl SpriteGpuInstance2d {
    const LAYOUT: wgpu::VertexBufferLayout<'static> = wgpu::VertexBufferLayout {
        array_stride: std::mem::size_of::<Self>() as wgpu::BufferAddress,
        step_mode: wgpu::VertexStepMode::Instance,
        attributes: &wgpu::vertex_attr_array![
            4 => Float32x4,
            5 => Float32x4,
            6 => Float32x4,
            7 => Float32x4,
            8 => Float32x4,
            9 => Float32x4,
        ],
    };
}

struct PreparedSpriteBatch2d {
    blend: engine_authoring::SpriteBlendMode,
    bind_group: wgpu::BindGroup,
    instance_buffer: wgpu::Buffer,
    count: u32,
}

/// GPU owner for the dedicated unlit Native 2D sprite phase.
pub(crate) struct Native2dGpuRenderer {
    quad: crate::mesh::GpuMesh,
    texture_bgl: wgpu::BindGroupLayout,
    pipelines: [wgpu::RenderPipeline; 3],
    nearest_sampler: wgpu::Sampler,
    linear_sampler: wgpu::Sampler,
    textures: std::collections::HashMap<usize, Arc<crate::material::Texture>>,
}

impl Native2dGpuRenderer {
    /// Creates the shared quad, sprite texture layout, and three blend pipelines.
    pub(crate) fn new(
        device: &wgpu::Device,
        camera_bgl: &wgpu::BindGroupLayout,
        format: wgpu::TextureFormat,
    ) -> Result<Self, crate::mesh::MeshValidationError> {
        let quad = crate::mesh::GpuMesh::upload(device, &crate::mesh::Mesh::quad())?;
        let texture_bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("Native 2D sprite texture BGL"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        multisampled: false,
                        view_dimension: wgpu::TextureViewDimension::D2,
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                    count: None,
                },
            ],
        });
        let layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("Native 2D sprite pipeline layout"),
            bind_group_layouts: &[Some(camera_bgl), Some(&texture_bgl)],
            immediate_size: 0,
        });
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("Native 2D sprite shader"),
            source: wgpu::ShaderSource::Wgsl(include_str!("shaders/sprite_2d.wgsl").into()),
        });
        let fragments = ["fs_alpha", "fs_premultiplied", "fs_additive"];
        let blends = [
            wgpu::BlendState::ALPHA_BLENDING,
            wgpu::BlendState {
                color: wgpu::BlendComponent {
                    src_factor: wgpu::BlendFactor::One,
                    dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
                    operation: wgpu::BlendOperation::Add,
                },
                alpha: wgpu::BlendComponent::OVER,
            },
            wgpu::BlendState {
                color: wgpu::BlendComponent {
                    src_factor: wgpu::BlendFactor::SrcAlpha,
                    dst_factor: wgpu::BlendFactor::One,
                    operation: wgpu::BlendOperation::Add,
                },
                alpha: wgpu::BlendComponent {
                    src_factor: wgpu::BlendFactor::One,
                    dst_factor: wgpu::BlendFactor::One,
                    operation: wgpu::BlendOperation::Add,
                },
            },
        ];
        let pipelines = std::array::from_fn(|index| {
            device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
                label: Some("Native 2D sprite pipeline"),
                layout: Some(&layout),
                vertex: wgpu::VertexState {
                    module: &shader,
                    entry_point: Some("vs_main"),
                    buffers: &[crate::mesh::Vertex::LAYOUT, SpriteGpuInstance2d::LAYOUT],
                    compilation_options: Default::default(),
                },
                fragment: Some(wgpu::FragmentState {
                    module: &shader,
                    entry_point: Some(fragments[index]),
                    targets: &[Some(wgpu::ColorTargetState {
                        format,
                        blend: Some(blends[index]),
                        write_mask: wgpu::ColorWrites::ALL,
                    })],
                    compilation_options: Default::default(),
                }),
                primitive: wgpu::PrimitiveState {
                    topology: wgpu::PrimitiveTopology::TriangleList,
                    front_face: wgpu::FrontFace::Ccw,
                    cull_mode: None,
                    ..Default::default()
                },
                depth_stencil: Some(wgpu::DepthStencilState {
                    format: wgpu::TextureFormat::Depth32Float,
                    depth_write_enabled: Some(false),
                    depth_compare: Some(wgpu::CompareFunction::Always),
                    stencil: wgpu::StencilState::default(),
                    bias: wgpu::DepthBiasState::default(),
                }),
                multisample: wgpu::MultisampleState {
                    count: crate::render_backend::MAIN_PASS_SAMPLE_COUNT,
                    ..Default::default()
                },
                multiview_mask: None,
                cache: None,
            })
        });
        let nearest_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
            label: Some("Native 2D nearest sampler"),
            address_mode_u: wgpu::AddressMode::ClampToEdge,
            address_mode_v: wgpu::AddressMode::ClampToEdge,
            address_mode_w: wgpu::AddressMode::ClampToEdge,
            mag_filter: wgpu::FilterMode::Nearest,
            min_filter: wgpu::FilterMode::Nearest,
            mipmap_filter: wgpu::MipmapFilterMode::Nearest,
            ..Default::default()
        });
        let linear_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
            label: Some("Native 2D linear sampler"),
            address_mode_u: wgpu::AddressMode::ClampToEdge,
            address_mode_v: wgpu::AddressMode::ClampToEdge,
            address_mode_w: wgpu::AddressMode::ClampToEdge,
            mag_filter: wgpu::FilterMode::Linear,
            min_filter: wgpu::FilterMode::Linear,
            mipmap_filter: wgpu::MipmapFilterMode::Linear,
            ..Default::default()
        });
        Ok(Self {
            quad,
            texture_bgl,
            pipelines,
            nearest_sampler,
            linear_sampler,
            textures: std::collections::HashMap::new(),
        })
    }

    fn gpu_texture(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        decoded: &Arc<DecodedTexture>,
    ) -> Option<Arc<crate::material::Texture>> {
        let key = Arc::as_ptr(decoded) as usize;
        if let Some(texture) = self.textures.get(&key) {
            return Some(Arc::clone(texture));
        }
        let texture = Arc::new(crate::material::Texture::from_decoded(device, queue, decoded).ok()?);
        self.textures.insert(key, Arc::clone(&texture));
        Some(texture)
    }

    /// Extracts, sorts, uploads, and batches current SpriteRenderer2D instances.
    fn prepare(
        &mut self,
        world: &mut engine_ecs::World,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
    ) -> Vec<PreparedSpriteBatch2d> {
        use crate::transform::GlobalTransform;
        use engine_ecs::Query;
        use wgpu::util::DeviceExt;

        let project = world
            .get_resource::<engine_authoring::Project2dSettings>()
            .cloned()
            .unwrap_or_default();
        let query = Query::<(&engine_authoring::SpriteRenderer2d, &SpriteRenderBindings2d, &GlobalTransform)>::new(world);
        let mut extracted = query
            .iter()
            .filter_map(|(entity, (renderer, bindings, global))| {
                if !renderer.visible {
                    return None;
                }
                let region = bindings.resolve(&renderer.sprite)?;
                let layer_rank = project
                    .sorting_layers
                    .iter()
                    .position(|layer| layer.id == renderer.sorting_layer)
                    .and_then(|rank| u32::try_from(rank).ok())
                    .unwrap_or(u32::MAX);
                let size = region.world_size();
                let pivot = glam::Vec2::from(region.pivot);
                let offset = glam::Vec3::new(
                    (0.5 - pivot.x) * size.x,
                    (pivot.y - 0.5) * size.y,
                    0.0,
                );
                let model = global.matrix()
                    * glam::Mat4::from_translation(offset)
                    * glam::Mat4::from_scale(glam::Vec3::new(size.x, size.y, 1.0));
                let mut u0 = region.uv_rect[0];
                let mut v0 = region.uv_rect[1];
                let mut u1 = region.uv_rect[2];
                let mut v1 = region.uv_rect[3];
                if renderer.flip_x {
                    std::mem::swap(&mut u0, &mut u1);
                }
                if renderer.flip_y {
                    std::mem::swap(&mut v0, &mut v1);
                }
                let columns = model.to_cols_array_2d();
                Some((
                    (layer_rank, renderer.order_in_layer, entity.id(), entity.generation()),
                    Arc::clone(&region.texture),
                    region.filtering,
                    renderer.blend,
                    SpriteGpuInstance2d {
                        model_0: columns[0],
                        model_1: columns[1],
                        model_2: columns[2],
                        model_3: columns[3],
                        tint: renderer.tint,
                        uv_transform: [u1 - u0, v1 - v0, u0, v0],
                    },
                ))
            })
            .collect::<Vec<_>>();
        extracted.sort_by_key(|entry| entry.0);

        let mut groups: Vec<(Arc<DecodedTexture>, engine_authoring::SpriteFiltering, engine_authoring::SpriteBlendMode, Vec<SpriteGpuInstance2d>)> = Vec::new();
        for (_, texture, filtering, blend, instance) in extracted {
            let compatible = groups.last().is_some_and(|(last_texture, last_filtering, last_blend, _)| {
                Arc::ptr_eq(last_texture, &texture) && *last_filtering == filtering && *last_blend == blend
            });
            if compatible {
                groups.last_mut().expect("compatible group exists").3.push(instance);
            } else {
                groups.push((texture, filtering, blend, vec![instance]));
            }
        }

        let mut prepared = Vec::with_capacity(groups.len());
        for (decoded, filtering, blend, instances) in groups {
            let Some(texture) = self.gpu_texture(device, queue, &decoded) else {
                continue;
            };
            let sampler = match filtering {
                engine_authoring::SpriteFiltering::Nearest => &self.nearest_sampler,
                engine_authoring::SpriteFiltering::Linear => &self.linear_sampler,
            };
            let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some("Native 2D sprite texture BG"),
                layout: &self.texture_bgl,
                entries: &[
                    wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&texture.view) },
                    wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(sampler) },
                ],
            });
            let instance_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: Some("Native 2D sprite instances"),
                contents: bytemuck::cast_slice(&instances),
                usage: wgpu::BufferUsages::VERTEX,
            });
            prepared.push(PreparedSpriteBatch2d {
                blend,
                bind_group,
                instance_buffer,
                count: instances.len() as u32,
            });
        }
        if let Some(metrics) = world.get_resource_mut::<Native2dRenderMetrics>() {
            metrics.sprite_count = prepared.iter().map(|batch| batch.count as usize).sum();
            metrics.sprite_batches = prepared.len();
        }
        prepared
    }

    fn draw<'a>(
        &'a self,
        pass: &mut wgpu::RenderPass<'a>,
        camera_bind_group: &'a wgpu::BindGroup,
        batches: &'a [PreparedSpriteBatch2d],
    ) {
        pass.set_bind_group(0, camera_bind_group, &[]);
        for batch in batches {
            let index = match batch.blend {
                engine_authoring::SpriteBlendMode::Alpha => 0,
                engine_authoring::SpriteBlendMode::PremultipliedAlpha => 1,
                engine_authoring::SpriteBlendMode::Additive => 2,
            };
            pass.set_pipeline(&self.pipelines[index]);
            pass.set_bind_group(1, &batch.bind_group, &[]);
            self.quad
                .draw_instanced(pass, &batch.instance_buffer, batch.count);
        }
    }
}

